'use strict';
const $=s=>document.querySelector(s), jobs=[{name:'채소 농업인',item:'상추',icon:'🥬',work:'채소밭',verb:'수확하기',desc:'작은 씨앗을 신선한 식탁으로',x:26,y:35,quiz:'상추를 신선하게 보관할 냉장 시설을 점검하는 역할은?',answers:['냉동·공조 설비 기술자','항공 관제사','출판 편집자'],correct:0},{name:'낙농업인',item:'우유',icon:'🥛',work:'목장',verb:'우유 모으기',desc:'건강한 젖소와 매일의 우유',x:72,y:31,quiz:'목장 동물의 질병을 진단하고 치료하는 전문가는?',answers:['조경사','수의사','상품 사진가'],correct:1},{name:'과수 농업인',item:'사과',icon:'🍎',work:'과수원',verb:'수확하기',desc:'계절을 돌보며 열매를 키워요',x:24,y:70,quiz:'과수원의 열매를 소비자에게 알리는 판매 전략을 세우는 역할은?',answers:['항해사','전력 설비 기술자','마케팅 담당자'],correct:2},{name:'양식 어업인',item:'생선',icon:'🐟',work:'양식장',verb:'출하하기',desc:'물의 환경을 살피며 함께 자라요',x:79,y:67,quiz:'수산물이 상하지 않게 온도를 유지하며 옮기는 일은?',answers:['냉장·냉동 운송','무대 연출','도서 분류'],correct:0}];
const weatherList=[{name:'맑음',icon:'☀️',factor:[1,1,1,1],news:'햇살이 좋은 날이에요. 작업장에서 첫 생산을 시작해 보세요.'},{name:'봄 축제 수요',icon:'🌤️',factor:[1.25,1.2,1.3,1.1],news:'소풍 준비가 시작되며 채소와 과일을 찾는 주민이 늘었어요.'},{name:'장날 · 맑음',icon:'☀️',factor:[1.1,1.15,.9,1.2],news:'장터가 열렸어요! 이웃과 생산물을 교환하고 필요한 재료를 모아요.'},{name:'폭우 · 정전',icon:'🌧️',factor:[1.4,1.35,1.2,1.5],news:'폭우로 배송이 지연됐어요. 시설 기술자의 역할을 알아보고 복구를 도와주세요.'},{name:'비 갠 뒤',icon:'🌈',factor:[1.1,1.05,1.1,1.2],news:'도로가 다시 열렸어요. 협력 식탁에 내 생산물을 보탤 수 있어요.'},{name:'풍작 장날',icon:'🌿',factor:[.8,.95,.8,1],news:'풍작으로 일부 가격이 내려갔어요. 판매 대신 교환이나 공동 식탁에 쓸 수도 있어요.'}];
const fresh=()=>({job:null,name:'나',day:1,coins:80,stock:[0,0,0,0],harvest:0,level:1,quizDay:0,knowledge:false,road:false,repaired:false,donated:[0,0,0,0],completed:false,history:['이음섬의 첫 번째 계절이 시작됐어요.'],place:'work'});
let state;try{state=JSON.parse(localStorage.getItem('ieum-v1'))}catch{}if(!state||!Array.isArray(state.stock))state=fresh();let tab='work',selected=state.job??0;
function save(){try{localStorage.setItem('ieum-v1',JSON.stringify(state))}catch{}}function log(t){state.history.unshift(t);state.history=state.history.slice(0,12)}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}function weather(){return weatherList[(state.day-1)%6]}function marketOpen(){return state.day%3===0}function price(i){return Math.round([10,14,12,16][i]*weather().factor[i])}function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function close(){ $('#dialog').close()}function modal(html){$('#dialogContent').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function render(){save();const j=jobs[state.job??0],w=weather();$('#coins').textContent=state.coins;$('#day').textContent=`${state.day}일째 · 봄`;$('#weather').textContent=`${w.icon} ${w.name}`;$('#map').classList.toggle('rain',w.name.includes('폭우')&&!state.repaired);$('#seasonBadge').textContent=state.completed?'🌼 공동 식탁 완성':state.day<4?'🌱 개인 성장 시즌':'🤝 협력 시즌';$('#profileIcon').textContent=j.icon;$('#jobName').textContent=state.job===null?'직업을 골라 주세요':j.name;$('#level').textContent=`${state.name}의 ${j.work} · ${state.level}단계`;$('#news').textContent=w.news;$('#phaseTitle').textContent=marketOpen()?'오늘은 장날! 이웃을 만나요':state.day>=4?'함께 차리는 식탁에 초대해요':'내 일에서 시작하는 작은 연결';$('#phaseDesc').textContent=marketOpen()?'교환하고 판매하며 서로에게 필요한 것을 찾아요.':`다음 장날까지 ${3-state.day%3}일 · 하루에 생산 3회, 직업 퀴즈 1회`;$('#priceGrid').innerHTML=jobs.map((x,i)=>`<div class="price"><span>${x.icon} ${x.item}</span><b>${price(i)} 🪙</b><span class="trend ${w.factor[i]>=1?'up':'down'}">${w.factor[i]===1?'— 기준가':`${w.factor[i]>1?'↑':'↓'} ${Math.round(Math.abs(w.factor[i]-1)*100)}%`}</span><small>1개 기준</small></div>`).join('');$('#inventory').innerHTML=jobs.map((x,i)=>`<span class="item">${x.icon} ${x.item} <b>${state.stock[i]}</b></span>`).join('');$('#inventoryTotal').textContent=`총 ${state.stock.reduce((a,b)=>a+b,0)}개`;$('#history').innerHTML=state.history.slice(0,4).map(t=>`<div class="entry">${escapeHtml(t)}</div>`).join('');$('#locations').innerHTML=jobs.map((x,i)=>`<button class="location ${state.job===i?'mine':''}" style="left:${x.x}%;top:${x.y}%" data-visit="${i}">${x.icon} ${x.work}<small>${state.job===i?escapeHtml(state.name)+' · 내 작업장':['서연','민준','지우','도윤'][i]+' · 가상 친구'}</small></button>`).join('')+`<button class="location" style="left:51%;top:53%" data-place="market">🏪 중앙 장터<small>${marketOpen()?'장터가 열렸어요':'3일마다 만나요'}</small></button><button class="location" style="left:51%;top:79%" data-place="season">${state.road?'🛤️':'🧺'} 공동 식탁<small>${state.completed?'함께 완성했어요':state.road?'연결 도로 완공':'협력 프로젝트'}</small></button>`;const pos=state.place==='market'?[48,55]:state.place==='season'?[48,78]:[j.x+3,j.y+6];$('#player').style.left=pos[0]+'%';$('#player').style.top=pos[1]+'%';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderPanel()}
function renderPanel(){const j=jobs[state.job??0],blocked=weather().name.includes('폭우')&&!state.repaired;if(tab==='work'){$('#panel').innerHTML=`<span class="eyetag">MY LITTLE WORKPLACE</span><h2>${j.work}의 하루</h2><span class="work-icon">${j.icon}</span><div class="stats"><span>오늘 생산 ${state.harvest} / 3회</span><span>한 번에 ${state.level+1}개</span></div><div class="progress"><i style="width:${state.harvest/3*100}%"></i></div>${blocked?'<div class="notice">🌧️ 폭우로 시설이 멈췄어요. 협력 시즌에서 전력 복구를 도와주세요.</div>':''}<button class="primary wide" data-action="harvest" ${state.harvest>=3||blocked?'disabled':''}>${j.verb} · ${j.item} +${state.level+1}</button><button class="wide secondary" data-action="quiz" ${state.quizDay===state.day?'disabled':''}>${state.quizDay===state.day?'✓ 오늘의 직업 퀴즈 완료':'💡 오늘의 직업 퀴즈 · 보너스 20코인'}</button><div class="building"><span>🏡</span><div><b>${state.level===1?'작은 작업장':'성장한 작업장'}</b><small>${state.level===1?'직업 퀴즈를 풀고 생산량을 늘려요':'한 번에 3개씩 생산할 수 있어요'}</small></div></div><button class="wide quiet" data-action="upgrade" ${state.level>=2?'disabled':''}>${state.level>=2?'✓ 작업장 확장 완료':'작업장 확장 · 60코인 + 직업 탐구'}</button>`}else if(tab==='market'){$('#panel').innerHTML=`<span class="eyetag">MARKET DAY</span><h2>${marketOpen()?'반가워요, 장날이에요!':'다음 장날에 만나요'}</h2><p>내 물건 2개와 친구의 물건 2개를 바꿔요. 이 체험의 친구들은 가상 주민이에요.</p>${!marketOpen()?`<div class="notice">장터는 3·6·9일째에 열려요.<br>다음 날로 이동하며 물건을 준비해 주세요.</div>`:''}${jobs.map((x,i)=>i===state.job?'':`<div class="offer"><b>${x.icon} ${['서연','민준','지우','도윤'][i]}의 ${x.item}</b><small>${j.item} 2개 ↔ ${x.item} 2개</small><button data-trade="${i}" ${!marketOpen()||state.stock[state.job]<2?'disabled':''}>교환 내용 확인</button></div>`).join('')}<button class="wide primary" data-action="sell" ${!marketOpen()||!state.stock[state.job]?'disabled':''}>내 ${j.item} 1개 판매 · ${price(state.job??0)}코인</button>`}else{const n=state.donated.reduce((a,b)=>a+b,0);$('#panel').innerHTML=`<span class="eyetag">BETTER TOGETHER</span><h2>${state.completed?'우리의 식탁이 완성됐어요':'함께 차리는 마을 식탁'}</h2><p>네 가지 생산물 각 2개를 모아요. 이웃의 물건은 장날 교환으로 구할 수 있어요.</p><div class="stats"><span>모인 재료</span><b>${n} / 8개</b></div><div class="progress"><i style="width:${n/8*100}%"></i></div>${jobs.map((x,i)=>`<div class="offer"><b>${x.icon} ${x.item} ${state.donated[i]} / 2</b><button data-donate="${i}" ${state.day<4||state.donated[i]>=2||state.stock[i]<1?'disabled':''}>${state.donated[i]>=2?'✓ 준비 완료':'1개 보태기'}</button></div>`).join('')}${state.day<4?'<p>협력 시즌은 4일째부터 열려요.</p>':''}${blocked?'<button class="wide secondary" data-action="repair">⚡ 전력 복구 미션</button>':''}<button class="wide quiet" data-action="road" ${state.road||state.day<4?'disabled':''}>${state.road?'✓ 우리 사이 연결 도로 완공':'🛤️ 연결 도로 만들기 · 30코인 + 역할 미션'}</button><button class="wide primary" data-action="complete" ${n<8||!state.road||state.completed||blocked?'disabled':''}>${state.completed?'🌼 함께 완성한 첫 번째 계절':'식탁으로 배송하기 · 보상 80코인'}</button>`}}
function showJobs(){selected=state.job??0;modal(`<span class="eyebrow">YOUR FIRST CHAPTER</span><h2>이 마을에서 어떤 일을 해볼까요?</h2><p>내 손으로 만들고, 이웃과 나누는 첫 번째 계절.<br>직업마다 서로에게 필요한 물건을 생산해요.</p><label for="name">마을에서 사용할 별명</label><input id="name" maxlength="12" value="${state.name==='나'?'':escapeHtml(state.name)}" placeholder="예: 새싹"><div class="job-grid">${jobs.map((j,i)=>`<button class="job-choice ${selected===i?'selected':''}" data-job="${i}"><span>${j.icon}</span>${j.name}<small>${j.desc}</small></button>`).join('')}</div><button class="primary wide" id="chooseJob">이 일로 마을 시작하기 →</button><p style="font-size:11px">혼자 체험하는 시제품이에요. 실제 학생 연결은 아직 적용되지 않았어요.</p>`);$('#chooseJob').onclick=()=>{state.job=selected;state.name=$('#name').value.trim()||'새싹';log(`${state.name}의 ${jobs[selected].work}에 첫 불이 켜졌어요.`);close();render()}}
function quiz(kind='daily'){const j=jobs[state.job],q=kind==='road'?{quiz:'비 온 뒤 안전한 도로를 연결하려면 어떤 일을 먼저 해야 할까요?',answers:['위험 구간을 점검하고 안전한 경로를 설계해요','빨리 가기 위해 통제 구간을 지나가요','지도 없이 가장 짧은 길만 골라요'],correct:0}:kind==='repair'?{quiz:'정전이 발생했을 때 마을의 안전한 대응은?',answers:['직접 전선을 만져 확인해요','위험 구역에서 떨어져 전문 기술자에게 알려요','젖은 전기 설비를 계속 사용해요'],correct:1}:j;modal(`<span class="eyebrow">일을 알면, 연결이 열려요</span><h2>${kind==='daily'?'오늘의 직업 탐험':kind==='road'?'토목·측량·안전의 연결':'전력 설비 기술자와 함께'}</h2><p>${q.quiz}</p>${q.answers.map((a,i)=>`<button class="wide" data-answer="${i}">${a}</button>`).join('')}<p id="feedback" role="status"></p><button class="quiet wide" data-close>나중에 할게요</button>`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.answer)!==q.correct){$('#feedback').textContent='다시 생각해 볼까요? 사람과 물건의 안전을 지키는 역할을 찾아보세요.';return}if(kind==='daily'){if(state.quizDay===state.day)return;state.quizDay=state.day;state.knowledge=true;state.coins+=20;log('직업 탐험 완료! 내 일에 연결된 다른 역할을 발견했어요.')}else if(kind==='road'){if(state.coins<30){toast('도로를 만들려면 30코인이 필요해요.');return}state.coins-=30;state.road=true;log('토목 설계·측량·시공·점검이 이어져 연결 도로를 만들었어요.')}else{state.repaired=true;log('전력 설비 기술자의 도움으로 작업장에 전기가 돌아왔어요.')}close();render();toast(kind==='daily'?'직업 탐험 완료! 20코인을 받았어요.':'함께 문제를 해결했어요!')})}
function act(a){if(state.job===null){showJobs();return}const i=state.job;if(a==='harvest'){if(state.harvest>=3||(weather().name.includes('폭우')&&!state.repaired))return;state.stock[i]+=state.level+1;state.harvest++;log(`${state.name}이(가) ${jobs[i].item} ${state.level+1}개를 생산했어요.`);toast(`${jobs[i].icon} ${jobs[i].item} +${state.level+1}! 장날에 이웃과 나눠 보세요.`)}if(a==='quiz'){if(state.quizDay!==state.day)quiz();return}if(a==='upgrade'){if(state.level>=2)return;if(!state.knowledge){toast('오늘의 직업 퀴즈로 연결된 역할을 먼저 알아보세요.');return}if(state.coins<60){toast('60코인이 필요해요. 퀴즈나 장날 판매로 모아 보세요.');return}state.coins-=60;state.level=2;log('내 작업장을 확장했어요. 한 번에 3개씩 생산해요.');toast('🏡 작업장이 한 단계 자랐어요!')}if(a==='sell'){if(!marketOpen()||state.stock[i]<1)return;state.stock[i]--;state.coins+=price(i);log(`${jobs[i].item} 1개를 ${price(i)}코인에 판매했어요.`);toast('판매 완료! 오늘 시세가 반영됐어요.')}if(a==='repair'){quiz('repair');return}if(a==='road'){if(state.day<4||state.road)return;if(state.coins<30){toast('도로 건설에는 30코인이 필요해요.');return}quiz('road');return}if(a==='complete'){if(state.completed||!state.road||state.donated.some(n=>n<2)||(weather().name.includes('폭우')&&!state.repaired))return;state.completed=true;state.coins+=80;log('네 가지 생산과 도로·전력·운송이 만나 공동 식탁을 완성했어요!');modal('<span class="work-icon">🥗</span><h2>우리의 일이 한 식탁에 모였어요.</h2><p>생산한 사람, 교환한 이웃, 길을 만든 사람, 전기를 복구한 사람. 모두의 일이 이어져 식탁이 완성됐어요.</p><div class="notice">공동 프로젝트 완료 · 80코인<br>이제 마을을 계속 가꾸거나 새 직업으로 시작할 수 있어요.</div><button class="primary wide" data-close>마을로 돌아가기</button>')}render()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))close();if(b.dataset.job!==undefined){selected=Number(b.dataset.job);document.querySelectorAll('[data-job]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.job)===selected))}if(b.dataset.tab){tab=b.dataset.tab;state.place=tab;render()}if(b.dataset.action)act(b.dataset.action);if(b.dataset.place){tab=b.dataset.place;state.place=tab;render()}if(b.dataset.visit!==undefined){const i=Number(b.dataset.visit);if(i===state.job){tab='work';state.place='work';render()}else{const j=jobs[i];modal(`<span class="eyebrow">이웃 작업장 · 가상 친구</span><h2>${['서연','민준','지우','도윤'][i]}의 ${j.work}</h2><span class="work-icon">${j.icon}</span><p>${j.item}를 만들고 있어요. ${jobs[state.job??0].item}와 교환하면 서로의 식탁을 채울 수 있어요.</p><div class="notice">생산에는 도구를 만드는 사람, 시설을 점검하는 사람, 물건을 운송하는 사람의 일도 필요해요.</div><button class="primary wide" id="goMarket">장터에서 만나기</button><button class="quiet wide" data-close>돌아가기</button>`);$('#goMarket').onclick=()=>{close();tab='market';state.place='market';render()}}}if(b.dataset.trade!==undefined){const i=Number(b.dataset.trade),mine=state.job;if(!marketOpen()||state.stock[mine]<2)return;modal(`<h2>이 물건으로 교환할까요?</h2><p>내 ${jobs[mine].item} 2개를 주고<br>가상 친구의 ${jobs[i].item} 2개를 받아요.</p><div class="dialog-actions"><button data-close>취소</button><button class="primary" id="confirmTrade">교환하기</button></div>`);$('#confirmTrade').onclick=()=>{if(!marketOpen()||state.stock[mine]<2)return;state.stock[mine]-=2;state.stock[i]+=2;log(`이웃의 ${jobs[i].item}와 내 ${jobs[mine].item}를 2개씩 교환했어요.`);close();render();toast('교환 완료! 서로에게 필요한 물건을 나눴어요.')}}if(b.dataset.donate!==undefined){const i=Number(b.dataset.donate);if(state.day<4||state.donated[i]>=2||state.stock[i]<1)return;state.stock[i]--;state.donated[i]++;log(`공동 식탁에 ${jobs[i].item} 1개를 보탰어요.`);render();toast('공동 식탁이 조금 더 채워졌어요!')}});
$('#nextDay').onclick=()=>{if(state.job===null){showJobs();return}state.day++;state.harvest=0;state.repaired=false;render();toast(`${state.day}일째 · ${weather().name}${marketOpen()?' · 장터가 열렸어요!':''}`)};$('#jobs').onclick=()=>{if(state.job===null){showJobs();return}modal('<h2>다음에는 다른 일을 해볼까요?</h2><p>이번 체험에서는 한 직업으로 계절을 보내요. 다른 직업을 고르려면 새로 시작하세요. 현재 진행은 초기화됩니다.</p><button class="primary wide" data-close>지금 직업으로 계속하기</button>')};$('#help').onclick=()=>modal('<span class="eyebrow">FIRST STEPS</span><h2>작은 마을의 하루</h2><p>① 직업을 고르고 하루 3번 생산해요.<br>② 직업 퀴즈를 풀고 작업장을 확장해요.<br>③ 다음 날로 이동하면 날씨와 시세가 변해요.<br>④ 3일마다 장터에서 다른 생산물을 구해요.<br>⑤ 4일째부터 네 재료를 각 2개씩 보태고, 도로를 만들어 공동 식탁을 완성해요.</p><div class="notice">실제 시간이 아닌 ‘다음 날로’ 버튼으로 진행해요. 친구와 거래, 시세는 체험용 시뮬레이션이에요.</div><button class="primary wide" data-close>해볼게요!</button>');$('#reset').onclick=()=>{modal('<h2>새 마을에서 시작할까요?</h2><p>이 브라우저에 저장된 코인, 물건, 건설, 활동 기록이 초기화됩니다.</p><div class="dialog-actions"><button data-close>계속하기</button><button class="primary" id="confirmReset">초기화하고 시작</button></div>');$('#confirmReset').onclick=()=>{state=fresh();tab='work';save();close();render();showJobs()}};$('#dialog').addEventListener('cancel',e=>{if(state.job===null)e.preventDefault()});render();if(state.job===null)showJobs();
